,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// File drop body area',
'const fileDropBody = document.querySelector(''#P1_REPORT .a-FileDrop-body'');',
'const fileInput = document.querySelector(''#P1_REPORT input[type="file"]'');',
'',
'// Remove old preview if it exists',
'const oldPreview = fileDropBody.querySelector(''.file-preview'');',
'if (oldPreview) oldPreview.remove();',
'',
'if (fileInput && fileInput.files.length > 0) {',
'    const file = fileInput.files[0];',
'    const fileType = file.type;',
'    const fileName = file.name;',
'',
'    let previewEl;',
'',
'    if (fileType.startsWith(''image/'')) {',
'        previewEl = document.createElement(''img'');',
'        previewEl.src = URL.createObjectURL(file);',
'        previewEl.style.maxWidth = ''100px'';',
'        previewEl.style.maxHeight = ''100px'';',
'    } else {',
'        previewEl = document.createElement(''div'');',
'        previewEl.textContent = fileName;',
'        previewEl.style.fontSize = ''14px'';',
'        previewEl.style.fontWeight = ''bold'';',
'    }',
'',
'    previewEl.classList.add(''file-preview'');',
'    fileDropBody.appendChild(previewEl);',
'}',
''))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(140589246931271418)
,p_process_sequence=>150
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload reports'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'BEGIN',
'    l_file_names := apex_string.SPLIT (',
'                        p_str => :P1_REPORT,',
'                        p_sep => '':'' );',
'',
'    IF l_file_names.count = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \0627\0644\062A\0642\0631\064A\0631 \0627\0644\062E\0627\0635 \0628\0643!'');'),
'    END IF;',
'',
'    SELECT *',
'      INTO l_file',
'      FROM APEX_APPLICATION_TEMP_FILES',
'     WHERE NAME = :P1_REPORT;',
'',
'    l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                        || DBMS_RANDOM.STRING(''x'', 8)',
'                        || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'',
'    l_request_url := :LOCATION_URI || l_file_name;',
'',
'    DBMS_CLOUD.put_object (',
'        credential_name => :CREDENTIAL_NAME,',
'        object_uri      => l_request_url,',
'        contents        => l_file.blob_content',
'    );',
'',
'    :P1_REPORT_URL := l_request_url;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P1_TYPE'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'report'
,p_internal_uid=>19977817340796090
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(140589654232271418)
,p_process_sequence=>160
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Reports Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P1_NAME IS NULL OR :P1_REPORT_URL IS NULL THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0627\062F\062E\0627\0644 \0627\0644\0628\064A\0627\0646\0627\062A \0623\0648\0644\0627'');'),
'    END IF;',
'',
'    IF NOT APEX_COLLECTION.collection_exists(''INDIVIDUALS_CARS_REPORTS'') THEN',
