||unistr(' \0623\0631\0634\0641\0629 \0627\0644\0637\0644\0628\060C \0648\0644\0627 \064A\062D\0642 \0644\064A \0627\0633\062A\0631\062F\0627\062F \0631\0633\0648\0645 \0627\0644\0637\0644\0628.</strong>'),
