wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(99356673789758878)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Photos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names        APEX_T_VARCHAR2;',
'    l_file              APEX_APPLICATION_TEMP_FILES%ROWTYPE;',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_request_filename	VARCHAR2(500);',
'    l_inner_folder  	VARCHAR2(500);',
'    v_item_name         VARCHAR2(255);',
'    ',
'    type itemsarray IS VARRAY(7) OF VARCHAR2(500); ',
'    items itemsarray;',
'    total integer;',
'BEGIN',
'    items   := itemsarray(:P4_FRONT_RIGHT_CORNER, :P4_FRONT_LEFT_CORNER, :P4_BACK_RIGHT_CORNER, :P4_BACK_LEFT_CORNER, :P4_FRONT_SEATS, :P4_BACK_SEATS, :P4_ODO_METER);',
'    total   := items.count;',
'',
'    -- Create a collection to store the images',
'    IF NOT APEX_COLLECTION.collection_exists(''PRODUCT_IMAGES'') THEN',
'        APEX_COLLECTION.create_collection(''PRODUCT_IMAGES'');',
'        APEX_COLLECTION.add_member (',
'            p_collection_name => ''PRODUCT_IMAGES'',',
'            p_c008 => ''false''',
'        );',
'    END IF;',
'',
'    FOR i in 1 .. total LOOP',
'        l_file_names := apex_string.SPLIT (',
'                            p_str => items(i),',
'                            p_sep => '':'' );',
'',
'        IF l_file_names.count > 0 THEN',
'            BEGIN',
'                SELECT *',
'                  INTO l_file',
'                  FROM APEX_APPLICATION_TEMP_FILES',
'                 WHERE NAME = items(i)',
'                   AND APPLICATION_ID = :APP_ID;',
'            EXCEPTION',
'                WHEN NO_DATA_FOUND THEN',
'                RAISE_APPLICATION_ERROR(-20003, ''NO DATA FOUND -> '' || items(i));',
'            END;',
'',
'            l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                        || DBMS_RANDOM.STRING(''x'', 8)',
'                        || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => l_file.MIME_TYPE);',
'           ',
'            l_request_url := :LOCATION_URI || l_file_name;',
'',
'            BEGIN',
'                DBMS_CLOUD.put_object (',
'                    credential_name => :CREDENTIAL_NAME,',
'                    object_uri      => l_request_url,',
'                    contents        => l_file.blob_content',
'                );',
'            EXCEPTION',
'                WHEN others THEN',
'                    SYSTEM_CONTROLS.ERROR_LOGS(',
'                        p_error_type    => ''SYSTEM_ERROR'',',
'                        p_process_name  => ''DBMS_CLOUD.put_object - App: '' || :APP_ID,',
'                        p_error_code    => -2,',
'                        p_error_message => ''URL: '' || l_request_url || '' - Filename: '' || l_file_name,',
'                        p_logger_name   => :APP_USER',
'                    );',
'            END;',
'',
'            -- Update the collection members with links',
'            APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE (',
'                p_collection_name => ''PRODUCT_IMAGES'',',
'                p_seq => ''1'',',
'                p_attr_number => i,',
'                p_attr_value => l_request_url',
'            );',
'        END IF;        ',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(99362710813758896)
,p_internal_uid=>12748654557377850
);
