wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(99357046089758878)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch images from collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    v_count NUMBER;',
'BEGIN',
'    SELECT count(1)',
'      INTO v_count',
'      FROM apex_collections',
'     WHERE collection_name = ''PRODUCT_IMAGES''',
'       AND seq_id = 1;',
'',
'    IF v_count > 0 THEN ',
'        SELECT c001, c002, c003, c004, c005, c006, c007',
'          INTO :P4_URL_1, :P4_URL_2, :P4_URL_3, :P4_URL_4, :P4_URL_5, :P4_URL_6, :P4_URL_7',
'          FROM apex_collections',
'         WHERE collection_name = ''PRODUCT_IMAGES''',
'           AND seq_id = 1;',
'    END IF;',
'END;'))
