 p_id=>wwv_flow_imp.id(213134317443731773)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert order'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P9_CREATE_REQUEST = 1 THEN',
'        IF LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P9_TYPE_SELLER) = ''owner'' THEN',
'            IF :P9_BUYER_TYPE = ''INDIVIDUAL'' THEN',
'                INSERT INTO INDIVIDUAL_PORTABLE_REQUESTS (BUYER_ID, BUYER_NAME, BUYER_TYPE, BUYER_NATIONAL_ID, BUYER_PHONE, REQUESTER_AS, STATUS, VERSION)',
'                    VALUES (:P9_BUYER_ID, :P9_NAME, :P9_BUYER_TYPE, :P9_NID, :P9_PHONE, :P9_TYPE_SELLER,',
'                        LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_request_status''),''V2'')',
'                RETURNING ID INTO :P9_ORDER_ID;',
'            ELSIF :P9_BUYER_TYPE = ''COMMERCIAL'' THEN',
'                INSERT INTO INDIVIDUAL_PORTABLE_REQUESTS (BUYER_ID, BUYER_NAME, BUYER_TYPE, BUYER_NATIONAL_ID, BUYER_PHONE, COMPANY_NAME, COMMERCIAL_REGISTER, AUTHORIZATION_NAME, AUTHORIZATION_NID, AUTHORIZATION_PHONE, REQUESTER_AS,',
'                                                          STATUS, VERSION)',
'                    VALUES (:P9_BUYER_ID, :P9_NAME, :P9_BUYER_TYPE, :P9_NID, :P9_PHONE, :P9_COMPANY_NAME, :P9_COMMERCIAL_REGISTER, :P9_COMMISSIONER_NAME, :P9_COMMISSIONER_ID_NUMBER, :P9_COMMISSIONER_MOBILE_NUMBER, :P9_TYPE_SELLER,',
'                        LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_request_status''),''V2'')',
'                RETURNING ID INTO :P9_ORDER_ID;',
'            END IF;',
'        ELSIF LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P9_TYPE_SELLER) = ''authorized'' THEN',
'            INSERT INTO INDIVIDUAL_PORTABLE_REQUESTS (BUYER_ID, BUYER_NAME, BUYER_TYPE, BUYER_NATIONAL_ID, BUYER_PHONE, AUTHORIZATION_NUMBER, AUTHORIZATION_DATE, AUTHORIZATION_ADDRESS, AUTHORIZATION_URL, REQUESTER_AS,',
'                                                      STATUS, VERSION)',
'                VALUES (:P9_BUYER_ID, :P9_NAME, :P9_BUYER_TYPE, :P9_NID, :P9_PHONE, :P9_AGENCY_NUM, :P9_AGENCY_DATE, :P9_AGENCY_PLACE, :P9_AGENCY_LICENSE_URL, :P9_TYPE_SELLER,',
'                        LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_request_status''),''V2'')',
'            RETURNING ID INTO :P9_ORDER_ID;',
'        ELSE',
'            RAISE_APPLICATION_ERROR(-20003, LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P9_TYPE_SELLER));',
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(211966045057143376)
,p_internal_uid=>26311366007233145
);
