wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(110365329389915123)
,p_process_sequence=>100
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Product Images (Not car case)'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    l_comma             VARCHAR2(3);',
'BEGIN',
'    IF NOT APEX_COLLECTION.collection_exists(''DROPZONE_UPLOAD'') THEN',
unistr('        RAISE_APPLICATION_ERROR(-20002, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \0635\0648\0631 \0627\0644\0645\0646\062A\062C'');'),
'    END IF;',
'',
'    FOR i IN ( SELECT c001 AS FILE_NAME, c002 AS MIME_TYPE, blob001 AS BLOB_CONTENT',
'                 FROM apex_collections',
'                WHERE collection_name = ''DROPZONE_UPLOAD''',
'    ) LOOP',
'        l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                            || DBMS_RANDOM.STRING(''x'', 8)',
'                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => i.MIME_TYPE);',
'',
'        l_request_url := :LOCATION_URI || l_file_name;',
'',
'        DBMS_CLOUD.put_object (',
'            credential_name => :CREDENTIAL_NAME,',
'            object_uri      => l_request_url,',
'            contents        => i.blob_content',
'        );',
'',
'        IF :P10_MORE_IMAGE = 1 THEN l_comma := '',''; END IF;',
'',
'        :P10_PRODUCT_IMAGES := :P10_PRODUCT_IMAGES || l_comma || l_request_url || '','';',
'    END LOOP;',
'',
'    :P10_PRODUCT_IMAGES := SUBSTR(:P10_PRODUCT_IMAGES, INSTR(:P10_PRODUCT_IMAGES, '','') + 1, LENGTH(:P10_PRODUCT_IMAGES) - 1);',
'    :P10_MAIN_IMAGE_URL := SUBSTR(:P10_PRODUCT_IMAGES, 1, INSTR(:P10_PRODUCT_IMAGES, '','') - 1);',
'',
'    -- TRUNCATE THE COLLECTION AFTER GET THE URLS',
'    APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''DROPZONE_UPLOAD'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P10_SUB_CATEGORY_ID'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_NOT_EQ_COND2'
,p_process_when2=>'&P10_CARS.'
,p_internal_uid=>10997948191146168
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(110364886883915124)
,p_process_sequence=>110
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert the Product'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count         NUMBER;',
'    v_product_id    NUMBER;',
'    v_main_image    VARCHAR2(30000);',
'    v_images        VARCHAR2(30000);',
'BEGIN',
'    -- Validate the product images (if the user not upload images)',
'    IF NOT APEX_COLLECTION.collection_exists(''PRODUCT_IMAGES'') AND :P10_SUB_CATEGORY_ID = :P10_CARS THEN',
unistr('        RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \062C\0645\064A\0639 \0635\0648\0631 \0627\0644\0645\0646\062A\062C \0627\0644\0645\0637\0644\0648\0628\0629'');'),
'    ELSIF APEX_COLLECTION.collection_exists(''PRODUCT_IMAGES'') AND :P10_SUB_CATEGORY_ID = :P10_CARS THEN',
'        -- Validate the product images (if the user not upload all images)',
'        FOR i IN (',
'            SELECT c001, c002, c003, c004, c005, c006, c007',
'              FROM apex_collections',
'             WHERE collection_name = ''PRODUCT_IMAGES''',
'               AND seq_id = 1',
'        ) LOOP',
'            IF (i.c001 IS NULL OR i.c002 IS NULL OR i.c003 IS NULL OR i.c004 IS NULL OR',
'               i.c005 IS NULL OR i.c006 IS NULL OR i.c007 IS NULL)',
'            THEN',
unistr('                RAISE_APPLICATION_ERROR(-20001, ''\064A\062C\0628 \0639\0644\064A\0643 \0631\0641\0639 \062C\0645\064A\0639 \0635\0648\0631 \0627\0644\0645\0646\062A\062C \0627\0644\0645\0637\0644\0648\0628\0629'');'),
'            END IF;',
'',
'            v_main_image := i.c001;',
'            v_images     := i.c002 || '', '' || i.c003 || '', '' || i.c004 || '', '' || i.c005 || '', '' || i.c006 || '', '' || i.c007;',
'        END LOOP;',
'    END IF;',
'',
'    IF :P10_SUB_CATEGORY_ID = :P10_CARS THEN',
'        v_images := v_images;',
'        v_main_image := v_main_image;',
'    ELSE',
'        v_images := :P10_PRODUCT_IMAGES;',
'        v_main_image := :P10_MAIN_IMAGE_URL;',
'    END IF;',
'',
'    IF :P10_PRODUCT_ID IS NULL THEN',
'        INSERT INTO PRODUCTS (',
'                CITY_ID, CATEGORY_ID, SUB_CATEGORY_ID, MAIN_IMAGE_URL, IMAGES_URLS, DESCRIPTION_AR, STATUS, IS_ACTIVE',
'            ) VALUES (',
'                :P10_CITY_ID, :P10_CATEGORY_ID, :P10_SUB_CATEGORY_ID, v_main_image, v_images, :P10_DESCRIPTION_AR,',
'                LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''available'', p_lookup_code => ''product_status''), 0',
'            ) RETURNING ID INTO v_product_id;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20001, ''Product Insertion Error'');',
'        END IF;',
'',
'        :P10_PRODUCT_ID := v_product_id;',
'',
'        IF :P10_SUB_CATEGORY_ID IN ( :P10_CARS, :P10_CAR_WITH_PLATE ) THEN',
'            SELECT COUNT(1)',
'              INTO v_count',
'              FROM INDIVIDUAL_PORTABLE_REQUESTS i,',
'                   CAR_DETAILS c',
'             WHERE i.PRODUCT_ID = c.PRODUCT_ID',
'               AND TRIM(c.CHASSIS_NUMBER) = TRIM(:P10_CHASSIS_NUMBER)',
'               AND i.BUYER_ID = :P10_BUYER_ID',
'               AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => i.STATUS) NOT IN (''publish_request'', ''canceled_request'')',
'               AND i.PRICING_PACKAGE IS NOT NULL;',
'            ',
'            IF v_count > 0 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20001, ''\0627\0644\0645\0646\062A\062C \0645\0648\062C\0648\062F \0628\0627\0644\0641\0639\0644  \064A\0631\062C\0649 \0627\0644\0630\0647\0627\0628 \0625\0644\0649 \0645\0632\0627\062F\0627\062A\064A \0644\0645\0634\0627\0647\062F\0629 \062A\0641\0627\0635\064A\0644 \0627\0644\0645\0646\062A\062C  \0623\0648 \0627\0644\062A\0648\0627\0635\0644 \0645\0639 \062E\062F\0645\0629 \0627\0644\0639\0645\0644\0627\0621 '');'),
'            END IF;',
'',
'            INSERT INTO CAR_DETAILS (',
'                    PRODUCT_ID, VEHICLE_MAKE_ID, VEHICLE_MODEL_ID, VEHICLE_EXTERNAL_COLOR_ID, VEHICLE_INNER_COLOR_ID, FUEL_TYPE_ID, ODO_METER, IS_THERE_DOCUMENT, IS_THERE_INSPECTION,',
'                    DOCUMENT_URL, INSPECTION_URL, YEAR, CHASSIS_NUMBER, IS_DROWNED, IS_BURNED, VEHICHLE_CATEGORY, PLATE_NUMBER, SERIAL_NUMBER, DROWING_INFO,',
'                    DROWING_FILE_URL, BURN_INFO, BURN_FILE_URL, ACCIDENT_FILE_URL, PREVIEW_TIMES, PREVIEW_ADDRESS, PREVIEW_MAP_URL,',
'                    TRANSMISSION_ID,AIRBAG_STATUS_ID',
'                ) VALUES (',
'                    v_product_id, :P10_VEHICLE_MAKE_ID, :P10_VEHICLE_MODEL_ID, :P10_VEHICLE_EXTERNAL_COLOR_ID, :P10_INNER_COLOR, :P10_FUEL_TYPE_ID, :P10_ODO_METER, :P10_IS_THERE_DOCUMENT, :P10_IS_THERE_INSPECTION,',
'                    :P10_DOCUMENT_URL, :P10_INSPECTION_URL, :P10_YEAR, :P10_CHASSIS_NUMBER, :P10_IS_DROWNED, :P10_IS_BURNED, :P10_VEHICHLE_CATEGORY, :P10_PLATE_NUMBER,',
'                    :P10_SEQUENCY_NUMBER, :P10_DROWING_INFO, :P10_DROWING_FILE_URL, :P10_BURN_INFO, :P10_BURN_FILE_URL, :P10_ACCIDENT_FILE_URL, :P10_PREVIEW_TIMES,',
'                    :P10_PREVIEW_ADDRESS, :P10_PREVIEW_MAP_URL, :P10_TRANSMISSION_TYPE_ID,:P10_AIRBAG_STATUS_ID',
'                );',
'',
'            IF SQL%ROWCOUNT = 0 THEN',
'                RAISE_APPLICATION_ERROR(-20002, ''Car details Insertion Error'');',
'            END IF;',
'        ELSIF :P10_SUB_CATEGORY_ID = :P10_PLATES THEN',
'',
'            SELECT COUNT(1)',
'              INTO v_count',
'              FROM INDIVIDUAL_PORTABLE_REQUESTS i,',
'                   CAR_DETAILS c',
'             WHERE i.PRODUCT_ID = c.PRODUCT_ID',
'               AND TRIM(c.PLATE_NUMBER) = TRIM(:P10_PLATE_NUMBER)',
'               AND i.BUYER_ID = :P10_BUYER_ID',
'               AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => i.STATUS) NOT IN (''publish_request'', ''canceled_request'')',
'               AND i.PRICING_PACKAGE IS NOT NULL;',
'',
'            IF v_count > 0 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20001, ''\0627\0644\0645\0646\062A\062C \0645\0648\062C\0648\062F \0628\0627\0644\0641\0639\0644  \064A\0631\062C\0649 \0627\0644\0630\0647\0627\0628 \0625\0644\0649 \0645\0632\0627\062F\0627\062A\064A \0644\0645\0634\0627\0647\062F\0629 \062A\0641\0627\0635\064A\0644 \0627\0644\0645\0646\062A\062C \0623\0648 \0627\0644\062A\0648\0627\0635\0644 \0645\0639 \062E\062F\0645\0629 \0627\0644\0639\0645\0644\0627\0621  '');'),
'            END IF;',
'',
'            INSERT INTO CAR_DETAILS ( PRODUCT_ID, PLATE_NUMBER, PLATE_TYPE, PREVIEW_TIMES, PREVIEW_ADDRESS, PREVIEW_MAP_URL, DOCUMENT_URL )',
'                VALUES ( v_product_id, :P10_PLATE_NUMBER, :P10_PLATE_TYPE, :P10_PREVIEW_TIMES, :P10_PREVIEW_ADDRESS, :P10_PREVIEW_MAP_URL, :P10_DOCUMENT_URL );',
'',
'            IF SQL%ROWCOUNT = 0 THEN',
'                RAISE_APPLICATION_ERROR(-20003, ''Car details Insertion Error'');',
'            END IF;',
'        END IF;',
'',
'        UPDATE INDIVIDUAL_PORTABLE_REQUESTS',
'           SET PRODUCT_ID           = :P10_PRODUCT_ID,',
'               MINIMUM_SELL_PRICE   = :P10_MINIMUM_ACCEPTABLE_PRICE',
'         WHERE ID = :P10_ORDER_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20004, ''Request updating Error'');',
'        END IF;',
'    ELSE',
'        UPDATE PRODUCTS',
'           SET CITY_ID          = :P10_CITY_ID,',
'               SUB_CATEGORY_ID  = :P10_SUB_CATEGORY_ID,',
'               MAIN_IMAGE_URL   = v_main_image,',
'               IMAGES_URLS      = v_images,',
'               DESCRIPTION_AR   = :P10_DESCRIPTION_AR',
'         WHERE ID = :P10_PRODUCT_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20005, ''Product Updating Error'');',
'        END IF;',
'',
'        IF :P10_IS_PREVIOUS = 0 THEN',
'            IF :P10_SUB_CATEGORY_ID IN ( :P10_CARS, :P10_CAR_WITH_PLATE ) THEN',
'                SELECT COUNT(1)',
'                  INTO v_count',
'                  FROM INDIVIDUAL_PORTABLE_REQUESTS i,',
'                       CAR_DETAILS c',
'                 WHERE i.PRODUCT_ID = c.PRODUCT_ID',
'                   AND TRIM(c.CHASSIS_NUMBER) = TRIM(:P10_CHASSIS_NUMBER)',
'                   AND i.BUYER_ID = :P10_BUYER_ID',
'                   AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => i.STATUS) NOT IN (''publish_request'', ''canceled_request'')',
'                   AND i.PRICING_PACKAGE IS NOT NULL;',
'                ',
'                IF v_count > 0 THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20001, ''\0627\0644\0645\0646\062A\062C \0645\0648\062C\0648\062F \0628\0627\0644\0641\0639\0644  \064A\0631\062C\0649 \0627\0644\0630\0647\0627\0628 \0625\0644\0649 \0645\0632\0627\062F\0627\062A\064A \0644\0645\0634\0627\0647\062F\0629 \062A\0641\0627\0635\064A\0644 \0627\0644\0645\0646\062A\062C \0623\0648 \0627\0644\062A\0648\0627\0635\0644 \0645\0639 \062E\062F\0645\0629 \0627\0644\0639\0645\0644\0627\0621 '');'),
'                END IF;',
'',
'            ELSIF :P10_SUB_CATEGORY_ID = :P10_PLATES THEN',
'                SELECT COUNT(1)',
'                  INTO v_count',
'                  FROM INDIVIDUAL_PORTABLE_REQUESTS i,',
'                       CAR_DETAILS c',
'                 WHERE i.PRODUCT_ID = c.PRODUCT_ID',
'                   AND TRIM(c.PLATE_NUMBER) = TRIM(:P10_PLATE_NUMBER)',
'                   AND i.BUYER_ID = :P10_BUYER_ID',
'                   AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => i.STATUS) NOT IN (''publish_request'', ''canceled_request'')',
'                   AND i.PRICING_PACKAGE IS NOT NULL;',
'',
'                IF v_count > 0 THEN',
unistr('                    RAISE_APPLICATION_ERROR(-20001, ''\0627\0644\0645\0646\062A\062C \0645\0648\062C\0648\062F \0628\0627\0644\0641\0639\0644  \064A\0631\062C\0649 \0627\0644\0630\0647\0627\0628 \0625\0644\0649 \0645\0632\0627\062F\0627\062A\064A \0644\0645\0634\0627\0647\062F\0629 \062A\0641\0627\0635\064A\0644 \0627\0644\0645\0646\062A\062C \0623\0648 \0627\0644\062A\0648\0627\0635\0644 \0645\0639 \062E\062F\0645\0629 \0627\0644\0639\0645\0644\0627\0621 '');'),
'                END IF;',
'            END IF;',
'        END IF;',
'',
'        SELECT COUNT(1)',
'          INTO v_count',
'          FROM CAR_DETAILS',
'         WHERE PRODUCT_ID = :P10_PRODUCT_ID;',
'',
'        IF v_count > 0 THEN',
'            UPDATE CAR_DETAILS',
'               SET VEHICLE_MAKE_ID              = :P10_VEHICLE_MAKE_ID,',
'                   VEHICLE_MODEL_ID             = :P10_VEHICLE_MODEL_ID,',
'                   VEHICLE_EXTERNAL_COLOR_ID    = :P10_VEHICLE_EXTERNAL_COLOR_ID,',
'                   VEHICLE_INNER_COLOR_ID       = :P10_INNER_COLOR,',
'                   FUEL_TYPE_ID                 = :P10_FUEL_TYPE_ID,',
'                   ODO_METER                    = :P10_ODO_METER,',
'                   IS_THERE_DOCUMENT            = :P10_IS_THERE_DOCUMENT,',
'                   IS_THERE_INSPECTION          = :P10_IS_THERE_INSPECTION,',
'                   DOCUMENT_URL                 = :P10_DOCUMENT_URL,',
'                   INSPECTION_URL               = :P10_INSPECTION_URL,',
'                   YEAR                         = :P10_YEAR,',
'                   CHASSIS_NUMBER               = :P10_CHASSIS_NUMBER,',
'                   IS_DROWNED                   = :P10_IS_DROWNED,',
'                   IS_BURNED                    = :P10_IS_BURNED,',
'                   VEHICHLE_CATEGORY            = :P10_VEHICHLE_CATEGORY,',
'                   PLATE_NUMBER                 = :P10_PLATE_NUMBER,',
'                   SERIAL_NUMBER                = :P10_SEQUENCY_NUMBER,',
'                   DROWING_INFO                 = :P10_DROWING_INFO,',
'                   DROWING_FILE_URL             = :P10_DROWING_FILE_URL,',
'                   BURN_INFO                    = :P10_BURN_INFO,',
'                   BURN_FILE_URL                = :P10_BURN_FILE_URL,',
'                   ACCIDENT_FILE_URL            = :P10_ACCIDENT_FILE_URL,',
'                   PREVIEW_TIMES                = :P10_PREVIEW_TIMES,',
'                   PREVIEW_ADDRESS              = :P10_PREVIEW_ADDRESS,',
'                   PREVIEW_MAP_URL              = :P10_PREVIEW_MAP_URL,',
'                   MINIMUM_ACCEPTABLE_PRICE     = :P10_MINIMUM_ACCEPTABLE_PRICE,',
'                   TRANSMISSION_ID              = :P10_TRANSMISSION_TYPE_ID,',
'                   AIRBAG_STATUS_ID             = :P10_AIRBAG_STATUS_ID',
'             WHERE PRODUCT_ID = :P10_PRODUCT_ID;',
'        END IF;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20006, ''Car details Updating Error'');',
'        END IF;',
'',
'        UPDATE INDIVIDUAL_PORTABLE_REQUESTS',
'           SET PRODUCT_ID           = :P10_PRODUCT_ID,',
'               MINIMUM_SELL_PRICE   = :P10_MINIMUM_ACCEPTABLE_PRICE',
'         WHERE ID = :P10_ORDER_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20007, ''Request updating Error'');',
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>10997505685146169
);
