,p_process_sequence=>130
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT Product Reports'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'BEGIN',
'    SELECT COUNT(SEQ_ID) INTO v_count FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''INDIVIDUALS_CARS_REPORTS'';',
'',
'    IF v_count > 0 THEN ',
'        FOR i IN ( SELECT c001, c002 FROM APEX_COLLECTIONS WHERE COLLECTION_NAME = ''INDIVIDUALS_CARS_REPORTS'' ORDER BY SEQ_ID ) LOOP',
'            ',
'            INSERT INTO INDIVIDUAL_REQUEST_ATTACHMENTS (CATEGORY, REQUEST_ID, FILE_NAME, URL, IS_ACTIVE )',
'                    VALUES (''PORTABLE'', :P10_ORDER_ID,  i.c001, i.c002,  1 );',
'            ',
'            IF SQL%ROWCOUNT = 0 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20002, ''\062E\0637\0623 \0641\064A \0625\0636\0627\0641\0629 \0627\0644\062A\0642\0631\064A\0631 \0627\0644\062C\062F\064A\062F'');'),
'            END IF;',
'        END LOOP;',
'            APEX_COLLECTION.truncate_collection ( p_collection_name => ''INDIVIDUALS_CARS_REPORTS'' );',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>10998371217146167
);
