wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(121002319424821307)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update payment details1'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result        NUMBER;',
'    l_message       VARCHAR2(1000);',
'    l_buyer_name    VARCHAR2(1000);',
'    l_pricing_plan  VARCHAR2(1000);',
'    l_name          VARCHAR2(1000);',
'BEGIN',
'    UPDATE INDIVIDUAL_PORTABLE_REQUESTS',
'       SET TRAN_ID       = :TRANID,',
'           PAY_RESULT    = :RESULT,',
'           RESPONSE_HASH = :RESPONSEHASH',
'     WHERE ID = :P12_ORDER_ID',
'       AND PRODUCT_ID = :P12_PRODUCT_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20002, ''INDIVIDUAL_CAR_REQUESTS Updating Error'');',
'    END IF;',
'',
'    INSERT INTO PAYMENT_TRANSACTIONS( REQUEST_ID, TYPE, PAYMENTID, TRANID, ECI, RESULT, TRACKID, AUTHCODE, RESPONSECODE, RRN, RESPONSEHASH, CARDBRAND, AMOUNT, USERFIELD1, USERFIELD3, USERFIELD4, USERFIELD5,',
'                CARDTOKEN, MASKEDPAN, EMAIL, PAYFOR, SUBSCRIPTIONID, PAYMENTTYPE, METADATA)',
'          VALUES(:P12_ORDER_ID, ''INDIVIDUALS_PORTABLE'', :PAYMENTID, :TRANID, :ECI, :RESULT, :TRACKID, :AUTHCODE, :RESPONSECODE, :RRN, :RESPONSEHASH, :CARDBRAND, :AMOUNT, :USERFIELD1, :USERFIELD3, :USERFIELD4, :USERFIELD5,',
'                 :CARDTOKEN, :MASKEDPAN, :EMAIL, :PAYFOR, :SUBSCRIPTIONID, :PAYMENTTYPE, :METADATA);',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20004, ''INSERTION ERROR'');',
'    END IF;',
'',
'    IF ( (:RESULT = ''Successful'') OR (:P12_IS_BYPASS = 1) ) THEN',
'        UPDATE INDIVIDUAL_PORTABLE_REQUESTS',
'           SET IS_PAID = 1,',
'               STATUS  = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''paid_request'', p_lookup_code => ''individual_request_status'')',
'         WHERE ID = :P12_ORDER_ID',
'           AND PRODUCT_ID = :P12_PRODUCT_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20003, ''INDIVIDUAL_CAR_REQUESTS Updating Error'');',
'        END IF;',
'',
'        UPDATE PRODUCTS',
'           SET IS_ACTIVE = 1',
'       WHERE ID = :P12_PRODUCT_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20004, ''PRODUCT Updating Error'');',
'        END IF;',
'',
'        -- SEND EMAIL TO THE ADMIN',
unistr('          SELECT BUYER_NAME, DECODE(PRICING_PACKAGE, ''A_99'',''\0628\0627\0642\0629 \0627\0644\0645\0631\0643\0628\0629 \0627\0644\0645\0641\062D\0648\0635\0647'',''B_149'',''\0628\0627\0642\0629 \0627\0644\0645\0631\0643\0628\0647 \0627\0644\063A\064A\0631 \0645\0641\062D\0648\0635\0647'',''C_399'',''\0627\0644\0628\0627\0642\0647 \0627\0644\0634\0627\0645\0644\0647'',''D_100'',''\0631\0633\0648\0645 \0627\0644\0625\0639\0644\0627\0646 \0639\0646 \0627\0644\0645\0632\0627\062F'',''F'','''')'),
'            INTO l_buyer_name, l_pricing_plan',
'            FROM INDIVIDUAL_PORTABLE_REQUESTS',
'           WHERE ID = :P12_ORDER_ID;',
'',
'          SELECT NAME_AR into l_name',
'            FROM PRODUCTS',
'           WHERE ID = :P12_PRODUCT_ID;',
'',
'        l_result := SYSTEM_CONTROLS.send_email ( ',
'                        p_to       => ''raghad.alqryan@mobasher.sa'', ',
unistr('                        p_subject  => ''\0625\0634\0639\0627\0631 \0628\0625\0646\0634\0627\0621 \0637\0644\0628 \062C\062F\064A\062F (\0645\0646\0642\0648\0644\0627\062A \0627\0644\0623\0641\0631\0627\062F)'','),
unistr('                        p_html     => ''\062A\0645 \0625\0646\0634\0627\0621 \0637\0644\0628 \062C\062F\064A\062F \0644\0644\0645\0634\062A\0631\064A: ''|| l_buyer_name'),
unistr('                                      ||''<br> \0644\0644\0645\0646\062A\062C: ''|| l_name'),
unistr('                                      ||''<br> \0648\0628\0627\0642\0629: ''|| l_pricing_plan'),
unistr('                                      ||''<br> \0648\0644\0645\0632\064A\062F \0645\0646 \0627\0644\062A\0641\0627\0635\064A\0644 \0627\0644\0631\062C\0627\0621 \0632\064A\0627\0631\0629 \0645\0646\0635\0629 \0627\0644\0625\062F\0627\0631\0629 \0627\0644\0639\0644\064A\0627'','),
'                        p_message  => l_message',
'                    );',
'',
'        IF l_result <> 1 THEN',
'            RAISE_APPLICATION_ERROR (-20005, l_message);',
'        END IF;',
'        ',
unistr('        APEX_APPLICATION.g_print_success_message := ''<span class="apex-success-msg">\062A\0645 \062A\0646\0641\064A\0630 \0637\0644\0628\0643 \0628\0646\062C\0627\062D</span>'';'),
'    ELSE',
unistr('        APEX_APPLICATION.g_print_success_message := ''<span class="apex-success-msg">\062A\0645 \062A\0646\0641\064A\0630 \0637\0644\0628\0643 \0628\0646\062C\0627\062D\060C \0648\0644\0643\0646 \064A\062C\0628 \0639\0644\064A\0643 \0625\0633\062A\0643\0645\0627\0644 \0625\062C\0631\0627\0621\0627\062A \0627\0644\062F\0641\0639 \0645\0646 \0645\0628\064A\0639\0627\062A\064A </span>'';'),
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>3198384644523608
);
